from collections.abc import Callable, Iterator

from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from . import models, schemas


def create_router(get_session: Callable[[], Iterator[Session]]) -> APIRouter:
    router = APIRouter()

    @router.post("/todos", response_model=schemas.TodoRead, status_code=201)
    def create(
        payload: schemas.TodoCreate, db: Session = Depends(get_session)
    ) -> models.Todo:
        row = models.Todo(**payload.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.delete("/todos" + "/{item_id}", status_code=204)
    def delete(item_id: int, db: Session = Depends(get_session)) -> None:
        row = db.get(models.Todo, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        db.delete(row)
        db.commit()

    @router.get("/todos", response_model=list[schemas.TodoRead])
    def list_items(
        completed: bool | None = None,
        limit: int = Query(default=20, ge=1, le=100),
        offset: int = Query(default=0, ge=0),
        db: Session = Depends(get_session),
    ) -> list[models.Todo]:
        stmt = select(models.Todo)
        if completed is not None:
            stmt = stmt.where(models.Todo.completed == completed)
        stmt = stmt.order_by(models.Todo.id).limit(limit).offset(offset)
        return list(db.scalars(stmt))

    @router.patch("/todos" + "/{item_id}", response_model=schemas.TodoRead)
    def patch(
        item_id: int, payload: schemas.TodoPatch, db: Session = Depends(get_session)
    ) -> models.Todo:
        row = db.get(models.Todo, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        for key, value in payload.model_dump(exclude_unset=True).items():
            setattr(row, key, value)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/todos" + "/{item_id}", response_model=schemas.TodoRead)
    def get(item_id: int, db: Session = Depends(get_session)) -> models.Todo:
        row = db.get(models.Todo, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        return row

    return router

